INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (16, '魁星楼', '我们眼前看到的建筑是魁星楼，楼刹为葫芦形，六角攒尖顶，灰瓦脊兽，檐内斗拱枋木交替，斗和耍头向外，檐角翘起，挑兽下铎风铃。始建年代无考，据清道光十一年（公元1831 年）的《重建奎楼山门碑》记载：“村南罕王庙巽地（东南）旧建文昌（魁星）楼，历有年矣。嘉庆戊辰岁（嘉庆十三年 1808 年）移建村外。不几年而基址裂，意神灵之不欲迁移……文昌（魁星）楼仍于村内旧址建立……”。魁星楼为二层挑角阁楼，高 10.5 米，阳台上的六方石基高 0.6 米，二层为砖灰结构，门阶向北，供奉的是魁星。魁星是主管功名、科举的神，我国很多地方都建有“魁星楼”或“魁星阁”，而且都是建在东南方向，对应八卦中的巽位。道家学说中称巽位有一种莫名的光亮，因此巽位就是明位，魁星楼建在巽位，寓意前途光明。没见过魁星的人也许会想，既然魁星是主管功名科考的，一定是位文质彬彬的白面书生吧？其实恰恰相反，魁星面目狰狞，金身青面，赤发环眼，头上还有两只角。您看魁星左手持一只墨斗，右手握一支大毛笔，称朱笔，相传被朱笔点中的人可以在科考中求得功名；左脚摆出扬起后踢的样子，脚心上是北斗七星；右脚金鸡独立，脚下踩着海中的一只大鳌鱼（一种大龟）的头部，意为“独占鳌头”。读书人在魁星楼拜魁星，祈求在科举考试中金榜题名。第二层供奉的是道教大神文昌君，也就是文曲星。文曲星两边分别是天聋地哑，一位聋，一位哑，可以保证科考中不泄题。传说魁星和文昌君原本就是同一位神，魁星是文昌君下凡。', '36.961857,111.973839', '{images_webp/kuixinglou.webp,images_webp/kuixinglou_1.webp,images_webp/kuixinglou_2.webp,images_webp/kuixinglou_3.webp,images_webp/kuixinglou_4.webp,images_webp/kuixinglou_5.webp,images_webp/kuixinglou_6.webp,images_webp/kuixinglou_7.webp,images_webp/kuixinglou_8.webp,images_webp/kuixinglou_9.webp,images_webp/kuixinglou_10.webp,images_webp/kuixinglou_11.webp,images_webp/kuixinglou_12.webp,images_webp/kuixinglou_13.webp,images_webp/kuixinglou_14.webp,images_webp/kuixinglou_15.webp,images_webp/kuixinglou_16.webp,images_webp/kuixinglou_17.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (39, '主街', NULL, NULL, '{}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (46, '关帝庙戏台', '我们眼前看到的是一座戏台，这个戏台建于清康熙48年，面阔三楹，进深四间。灰瓦卷棚加歇山造顶。“楷模”原先悬于此处。匾托上雕有两只蝙蝠，下有四条莲花垂柱，安头为大象，中间圆形的为圆寿，寓意为福寿相连。每年的四月初八白天在这里上演木偶戏，晚上挂上幕布就可演皮影戏。古堡范围虽然不是很大，但在这么小的村落里居然有三座戏台，这只是其中的第一座。它很有效的利用了空间，关起门来是戏台，打开门是过道。还有一特点便是：与山门相连，山门连体乐台是张壁古堡的独创，是张壁人在建筑时所做的一种尝试，也是艺术与实用相结合的产物。', '36.968294,111.979872', '{images_webp/guandimiaoxitai_1.webp,images_webp/guandimiaoxitai_2.webp,images_webp/guandimiaoxitai_3.webp,images_webp/guandimiaoxitai_4.webp,images_webp/guandimiaoxitai_5.webp,images_webp/guandimiaoxitai_6.webp,images_webp/guandimiaoxitai_7.webp,images_webp/guandimiaoxitai_8.webp,images_webp/guandimiaoxitai_9.webp,images_webp/guandimiaoxitai_10.webp,images_webp/guandimiaoxitai_11.webp,images_webp/guandimiaoxitai_12.webp,images_webp/guandimiaoxitai_13.webp,images_webp/guandimiaoxitai_14.webp,images_webp/guandimiaoxitai_15.webp,images_webp/guandimiaoxitai_16.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (47, 'LBMR沉睡的古堡体验区', '前方到达的就是张壁古堡 LBMR 项目的体验区。现如今，沉浸式虚拟现实技术正逐渐成为旅游业的一项重要创新。LBMR（Location-Based Mixed Reality，基于位置的混合现实）是一种结合了物理世界与虚拟世界的体验技术，用户在一个特定的地理或物理空间中与虚拟元素进行交互。张壁古堡是一座拥有千年历史的文化遗产，承载了无数历史故事和文化记忆，景区内保存有大量的古建筑、碑刻、壁画等文物和传统文化。张壁古堡 LBMR 项目，在大空间 VR 的基础上，实现了在元宇宙中再建一个张壁古堡，把古堡的文化、建筑等元素以模型创造的方式呈现，让观众不仅能“看到”历史，更能“走进”历史，与古人进行跨时空的交流，让静态文化借助高科技手段得到全息展示。对张壁古堡军事、星象、琉璃等文化进行创造性转化，使文化更有吸引力和感染力，真正做到“让文物活起来”，激发游客对历史文化产生兴趣的同时增强对文化遗产的保护意识。项目占用面积 1000 平方米，支持多用户、多目标同时互动；低延迟、高清晰度，增强了虚拟环境的真实感和吸引力；通过深度神经网络实现高精度的人体姿态捕捉，将用户的每一个动作精确地映射到虚拟世界，增强虚拟与现实的交互融合；并能够识别和解析复杂的人体动作和微妙的表情变化，提供更丰富和精细的交互可能。这样一处沉浸式的体验项目与古军事地道的完美融合，可直接让我们穿越其中。里面的“场景”、文化完全根植于景区，对我们接来在古堡的参观有更直观的记忆和互动，虚实结合，建议体验。', '36.960530,111.972620', '{images_webp/LBMRchengshuidegubaotiyanqu_1.webp,images_webp/LBMRchengshuidegubaotiyanqu_2.webp,images_webp/LBMRchengshuidegubaotiyanqu_3.webp,images_webp/LBMRchengshuidegubaotiyanqu_4.webp,images_webp/LBMRchengshuidegubaotiyanqu_5.webp,images_webp/LBMRchengshuidegubaotiyanqu_6.webp,images_webp/LBMRchengshuidegubaotiyanqu_7.webp}', 'Scenic area official');
