INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (44, '二郎庙戏台', '二郎庙戏台比我们常见的戏台高,因为古代建戏台是为了取悦神灵，二郎庙位置较高,所以戏台也建得很高。原先每年农历七月十八村子赶庙会时都会在这里唱三天大戏。不过为了保护文物，现在已经不使用了。', '36.964076,111.972945', '{images_webp/erlangmiaoxitai_1.webp,images_webp/erlangmiaoxitai_2.webp,images_webp/erlangmiaoxitai_3.webp,images_webp/erlangmiaoxitai_4.webp}', 'Scenic area official');
