INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (74, '校场', '主街西侧的第一个巷子名叫西场。西场原本是校场，是演武练兵之所，随着时间的推移，张壁由军镇演变成普通的设防性村落，渐渐有人在校场起房盖舍变成实际的居民区。', '36.962027,111.973366', '{images_webp/jiaochang_1.webp,images_webp/jiaochang_2.webp,images_webp/jiaochang_3.webp,images_webp/jiaochang_4.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (10, '古灯杆', '道光十一年（1831年）的《重建奎楼山门碑记》里记载：“……旁立灯杆一座，元灯不坠……”灯杆高12米，古有“张壁点灯，介休看明”的说法，1994年清华大学的赖德林教授实地考察对此提出质疑，于是他便徒步从张壁村走往介休，途中经过一些村落时他发现有一些寨子的遗址，而且每个寨子的至高点都有烽火台的遗迹，赖德霖教授找到了原因，这里的信号灯点燃的话，各个至高点上的烽火台都会相继点燃依次这样传递下去。这样不仅能照明整个介休城，甚至更远的地方都可以收到信号。张壁古灯究竟谁人所立，我们不得而知，但与古代军事时期惯用的烽火台相似的张壁信号灯，在历史上一定发挥过重要的信息联络作用，这也可作为古堡曾是一处重要军事壁垒设施的有力佐证。', '36.961695,111.973676', '{images_webp/gudenggan.webp,images_webp/gudenggan_1.webp,images_webp/gudenggan_2.webp,images_webp/gudenggan_3.webp,images_webp/gudenggan_4.webp}', 'Scenic area official');
