INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (12, '古照壁', NULL, NULL, '{images_webp/guzhaobi.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (13, '槐抱柳', '原先村子里有六棵古槐树对应天空中南斗六星所栽，斗宿主生，表达了古堡人对生生不息的期盼。但在1947年战火烧毁了后面的兴隆寺并且殃及了六棵古槐树，五棵古槐被烧毁，仅留一颗奄奄一息。当地百姓为救活这颗古槐便在其根部种了一棵柳树，现在我们可以看到两棵树的树根都长在一起了。专家考证，槐树有1000多年的树龄，柳树有70余年的树龄。所以村民也称其为“千年古槐抱杨柳”。', '36.962959,111.973107', '{images_webp/huaibaoliu.webp}', 'Scenic area official');
