INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (15, '空王行祠', '空王行祠建于明万历四十一年（公元1613年）距今已经有407年的历史。殿中供奉的是空王古佛田志超，他是汉人成佛第一尊。主脊中央有葫芦宝瓶，两侧宝瓶下方各有一只狮子被称之为狮瓶风水楼，用来护佑平安的。葫芦宝瓶里装有五谷，寓意五谷丰登。正中葫芦宝瓶下方有一座二层阁楼，下层供奉的是现在佛释迦牟尼佛，上面一层供奉未来佛弥勒佛。（阁楼里传说供奉的是姜子牙，相传姜子牙在封神时并没有给自己留有一官半职，他说要为老百姓看家护院，于是老百姓就修建二层阁楼来供奉姜子牙）。葫芦宝瓶前后有几条铁链被称作是无关紧要，平时不起任何作用，刮风下雨的时候来回牵扯可以保持瓶身的稳定。四个屋檐角上各有一名武士，被称作是走投无路，因为向前走一步便会掉入万丈深渊。相传这四位武士分别是周瑜、韩信、庞涓、罗成四位将军，这四人都是才华横溢，能耐过人，但是他们却刚愎自用，攻于算计，英年早逝。在屋檐角上供奉他们是为了警示后人，做人做事不要太绝，要留有余地，否则就会走投无路。在主脊两端有螭吻，螭吻是龙生九子之一，它好高喜水能镇宅。因为古代的建筑都是木质结构的，供奉螭吻以避火患。', '36.963465,111.973063', '{images_webp/kongwangxingci.webp,images_webp/kongwangxingci_1.webp,images_webp/kongwangxingci_2.webp,images_webp/kongwangxingci_3.webp,images_webp/kongwangxingci_4.webp,images_webp/kongwangxingci_5.webp,images_webp/kongwangxingci_6.webp,images_webp/kongwangxingci_7.webp,images_webp/kongwangxingci_8.webp,images_webp/kongwangxingci_9.webp,images_webp/kongwangxingci_10.webp,images_webp/kongwangxingci_11.webp,images_webp/kongwangxingci_12.webp,images_webp/kongwangxingci_13.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (17, '姥姥院', NULL, NULL, '{images_webp/laolaoyuan.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (18, '龙鹤福', '这是个福字，也有人说它更像个活字，所以它是写活了的福字。您看左边以草书开头，看起来特别像一条龙，龙是古代对权利的象征，表达了主人望子成龙，希望后人飞黄腾达之意；右边本是一口田，“一”用行书写成了鹤首，有话说千年鹤，万年龟，是民间祈盼长寿的符号；中间的一个口字填实了，表示家境殷实，粮食充裕，吃的很饱，口里不空。而且老百姓常说“病从口入，祸从口出”将口填满了，也可以起到消灾灭祸的作用；下方的田字规规矩矩用楷体书写，说明无论个人有多大的发展都必须以田为本，规规矩矩种田，规规矩矩做人。
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (19, '龙神庙遗址', NULL, NULL, '{}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (20, '吕祖阁', '正中供奉吕祖，就是八仙之一的吕洞宾，
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (21, '南堡门', '南堡门也称永护门，修建于明嘉靖38年，公元 1559年，距今467年。全部由青石拱制，拱门上方的石匾额书有“护村镇河”四字。原先在南堡门外有一条河流，人们担心河水泛滥危害到村民，为了寻求心理的安慰，在上方雕了一只吸水的神兽，被老百姓叫做“汲水兽”。汲水兽——性善好水，能调节水量，少能载船，多不淹河，保佑一方平安，备受百姓崇敬，寓意永避水害长存久安。', NULL, '{images_webp/nanbaomen.webp,images_webp/nanbaomen_1.webp,images_webp/nanbaomen_2.webp,images_webp/nanbaomen_3.webp,images_webp/nanbaomen_4.webp,images_webp/nanbaomen_5.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (22, '农耕院', NULL, NULL, '{images_webp/nonggengyuan.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (23, '清宁堂', NULL, NULL, '{images_webp/qingningtang.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (24, '七星槐', NULL, NULL, '{images_webp/qixinghuai.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (27, '双龙碾', '双龙碾，最初这个碾子被放在堡外北边碾头地里，后来由于关帝庙的僧人比较多，香火很旺，僧人们为了方便碾粮食就把碾子放在了这里。之所以说他古老，是因为大家可以看到它的碾齿全部磨平了。它和别的碾子一样都是由碾滚，碾盘，冲天轴，还有靠人推或者畜力拉的碾杆四部分组成。相传很早以前这个碾子很是不一般，用过它的人都说用它碾的轻便，碾出的粮食口感好，更有奇怪的一点，相传村里有个年轻人，有天拿了一升粮来碾，但碾了一整天都没有碾完，这样的事情传开后老百姓觉得它非常的神奇，纷纷到此碾作，从此碾道里人山人海，非常壮观。但是有一天，碾房草棚着火了，村里打更巡夜的人呼叫老百姓前来救火，火被扑灭之后，草棚不见了，水淋淋的碾滚上显现出了龙形图样，这时所有老百姓全部跪倒在地，磕头祷告。她们更相信碾子具有灵气了，再仔细一看，发现碾盘也有龙形图案。从此，双龙碾一词便在坊间传开了。后来她们发现经此一劫，碾子的灵气失去了。只留给人们一个浇水现龙的奇观。另一方面，古堡的历史相当悠久，来到这样一方古老的土地上，当然也要了解它的民俗文化了，这个碾子就成为我们了解民俗文化的一个载体。', '36.961827,111.972839', '{images_webp/shuanglongnian.webp,images_webp/shuanglongnian_1.webp,images_webp/shuanglongnian_2.webp,images_webp/shuanglongnian_3.webp,images_webp/shuanglongnian_4.webp,images_webp/shuanglongnian_5.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (28, '围棋院', NULL, NULL, '{images_webp/weiqiyuan.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (29, '瓮城', '瓮城：站在此处看到的就是张壁古堡的瓮城，瓮城是古代城市主要的防御设施之一。在城门外加筑小城，高与大城相同，其形状或圆或方。圆者似瓮，故称瓮城；方者则称之方城。瓮城设在侧面，从而增强了防御能力。当敌人攻入瓮城时，如将主城门和瓮城门关闭，守军即可对敌人形成“瓮中捉鳖”之势。
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (30, '西场巷巷门', NULL, NULL, '{images_webp/xichangxiangxiangmen.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (31, '西方圣境殿', '西方圣境殿位于南堡门之上，正殿为三间悬山小屋，面阔九米，进深四点二米，坐南面北。殿前雍正九年（公元1731年）的《重修金妆西方圣境碑》中记载：“建殿年代不详，康熙五十九年（1720年）‘纳子’传学起意修葺金妆，雍正八、九年，各项工程次第完成。”碑文中还记载：“乐善者思勉于善，为善者益坚于善，一乡而皆善也，其俗进于淳。”体现了古堡百姓的民风淳朴、乐善好施，其中的“思勉”是出自于弟子规中的“道人善即是善,人知之愈思勉”。所以说，西方圣境殿既是信仰神灵也是劝人为善、教化众生的地方。大殿正中供奉的是接引有缘众生往生西方净土的阿弥陀佛，两侧供奉观音菩萨和大势至菩萨。原先殿内的悬塑为十八重天、十八重地，后期遭到破坏，我们现在看到的悬塑是2013年聘请工艺美术学家万绪德先生重新塑造，悬塑内容为伎乐天，描写了佛国的歌舞升平。', '36.961823,111.973526', '{images_webp/xifangshengjingdian.webp,images_webp/xifangshengjingdian_1.webp,images_webp/xifangshengjingdian_2.webp,images_webp/xifangshengjingdian_3.webp,images_webp/xifangshengjingdian_4.webp,images_webp/xifangshengjingdian_5.webp,images_webp/xifangshengjingdian_6.webp,images_webp/xifangshengjingdian_7.webp,images_webp/xifangshengjingdian_8.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (32, '兴隆寺', NULL, NULL, '{images_webp/xinglongsi.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (33, '星象文化展厅', '张壁古堡是一处经历了由军事到民俗，由堡到村发展过程的军事堡垒，这里的很多建筑是对应天上的28星宿所建，接下来我们去看一处星象文化展馆。首先我们来了解一下星象文化的历史沿革。
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (34, '研学院', NULL, NULL, '{images_webp/yanxueyuan.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (75, '军校场 点将台', '校场的点将台位于张壁古堡南堡门左侧斜坡的校场内，点将台见证了古堡曾经的军事辉煌，古时将领可能在此点兵遣将，指挥军事训练和作战。如今，点将台周边陈列着几尊铁像、几台战车，还原了古代战争场面，游客可以在此感受历史的厚重，领略古代军事文化的魅力。', '36.962027,111.973366', '{images_webp/junjiaochangdianjiangtai_1.webp,images_webp/junjiaochangdianjiangtai_2.webp,images_webp/junjiaochangdianjiangtai_3.webp,images_webp/junjiaochangdianjiangtai_4.webp,images_webp/junjiaochangdianjiangtai_5.webp,images_webp/junjiaochangdianjiangtai_6.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (35, '永春楼', '永春楼、联辉：贾家巷位于堡内的西侧，巷门颇有气势，建于何时无考，是全堡最高的一座门楼。门楼邻街一侧的匾额题有“永春楼”，巷内一侧题有“联辉”。永春楼巷门与奎星楼隔街相望，相距约百余米。联辉取意于“奎壁联辉”，古堡中有魁星楼，有位于“壁宿”的北堡门，贾家巷中住的又是堡中的商贾大户，自然希望子孙能世代书香抬高门第，所以在巷门扁上题上“联辉”，其喻意一目了然。另一种解释也很有道理：贾家巷不仅住着最富有的人家——张礼维，同时还住着其它几户很富有的商人，张礼维希望大家可以联合起来共创辉煌，所以说联辉也是晋商精神的一种重要体现。', '36.962534,111.973354', '{images_webp/yongchunlou.webp,images_webp/yongchunlou_1.webp,images_webp/yongchunlou_2.webp,images_webp/yongchunlou_3.webp,images_webp/yongchunlou_4.webp,images_webp/yongchunlou_5.webp,images_webp/yongchunlou_6.webp,images_webp/yongchunlou_7.webp,images_webp/yongchunlou_8.webp,images_webp/yongchunlou_9.webp,images_webp/yongchunlou_10.webp,images_webp/yongchunlou_11.webp,images_webp/yongchunlou_12.webp,images_webp/yongchunlou_13.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (36, '扎染坊', NULL, NULL, '{images_webp/zharanfang.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (37, '真武殿', '真武庙重建于嘉庆十三年，公元1808年,距今已有216年的历史。因为真武大帝是掌管北方的水神，所以将庙宇建在北
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (38, '中央戊己土', NULL, NULL, '{images_webp/zhongyangwujitu.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (41, '门票', NULL, NULL, '{}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (42, '其他', NULL, NULL, '{}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (59, '文殊菩萨', '殿内供奉的是琉璃所烧制的塑像，文殊菩萨是佛教中智慧的象征，在佛教中表征般若，主司智慧，是大乘佛教四大菩萨之一，常见形象为顶结五髻，代表大日如来的五智，一手持莲花，上置般若经卷，一手持宝剑，象征智慧锐利，能断无明烦恼，坐骑为青狮，表示智慧威猛。道场为山西五台山。', '36.960530,111.972618', '{images_webp/wenshupusa_1.webp,images_webp/wenshupusa_2.webp,images_webp/wenshupusa_3.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (48, '空王行祠琉璃碑', '空王行祠廊下两通烧制于明万历年代的孔雀蓝琉璃碑，是全国乃至全世界仅存的两通，曾经登上《国宝档案》栏目。如此珍贵主要有以下几个原因：一是颜色珍贵，因为孔雀蓝色的烧制工艺失传；二是历史悠久，烧制于明万历年间，距今已有四百多年的历史；三是通体烧制，烧制以及搬运都是一个复杂困难的过程，所以能留存下来非常不易。琉璃碑分为碑首、碑身、碑座三个部分。碑首为双龙盘踞；碑身为孔雀蓝的烧制工艺；碑座为瓜皮条釉。左手边是《宽贤发愿碑》落款为万历三十三年三月ニ十三日。右手边是《创建空王行祠碑记》落款为万历41年（1613年）。', '36.963465,111.973063', '{images_webp/kongwangxingciliulibei_1.webp,images_webp/kongwangxingciliulibei_2.webp,images_webp/kongwangxingciliulibei_3.webp,images_webp/kongwangxingciliulibei_4.webp,images_webp/kongwangxingciliulibei_5.webp,images_webp/kongwangxingciliulibei_6.webp,images_webp/kongwangxingciliulibei_7.webp,images_webp/kongwangxingciliulibei_8.webp,images_webp/kongwangxingciliulibei_9.webp,images_webp/kongwangxingciliulibei_10.webp,images_webp/kongwangxingciliulibei_11.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (49, '四大菩萨', '来到这个院落看到的四尊菩萨是 2018 年请回来的。右边第一尊骑青狮的为文殊菩萨，也叫大智菩萨，道场在山西五台山。第二尊观音菩萨也叫大悲菩萨，道场在浙江普陀山。第三尊手握金刚杵的为地藏王菩萨也叫大愿菩萨，道场在安徽九华山。最后一位骑六牙白象的普贤菩萨也叫大行菩萨，道场为四川峨眉山。', '36.961477,111.973899', '{images_webp/sidapusa_1.webp,images_webp/sidapusa_2.webp,images_webp/sidapusa_3.webp,images_webp/sidapusa_4.webp,images_webp/sidapusa_5.webp,images_webp/sidapusa_6.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (50, '泥包铁像', '泥包铁像：我们看到的拱形建筑是山西很常见的窑洞。
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (51, '四大菩萨—文殊菩萨', '第一尊骑青狮的为文殊菩萨，也叫大智菩萨，道场在山西五台山。', '36.961549,111.973789', '{images_webp/sidapusawenshupusa_1.webp,images_webp/sidapusawenshupusa_2.webp,images_webp/sidapusawenshupusa_3.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (52, '四大菩萨—观音菩萨', '第二尊观音菩萨也叫大悲菩萨，道场在浙江普陀山', '36.961556,111.973825', '{images_webp/sidapusaguanyinpusa_1.webp,images_webp/sidapusaguanyinpusa_2.webp,images_webp/sidapusaguanyinpusa_3.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (53, '四大菩萨—地藏王菩萨', '第三尊手握金刚杵的为地藏王菩萨也叫大愿菩萨，道场在安徽九华山。', '36.961578,111.973880', '{images_webp/sidapusadizangwangpusa_1.webp,images_webp/sidapusadizangwangpusa_2.webp,images_webp/sidapusadizangwangpusa_3.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (54, '四大菩萨—普贤菩萨', '最后一位骑六牙白象的普贤菩萨也叫大行菩萨，道场为四川峨眉山。', '36.961597,111.973926', '{images_webp/sidapusapuxianpusa_1.webp,images_webp/sidapusapuxianpusa_2.webp,images_webp/sidapusapuxianpusa_3.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (55, '西方圣境殿 阿弥陀佛', '阿弥陀佛（梵语Amitābha），又名无量佛、无量光佛、无量寿佛等。大乘经载，阿弥陀佛在过去久远劫时曾立大愿，建立西方净土，广渡无边众生，成就无量庄严功德，为大乘佛教所广为崇敬和弘扬。大乘佛经主要如《无量寿经》、《阿弥陀经》、《观无量寿佛经》，对阿弥陀佛及其西方极乐世界均有详述。大乘佛教流传之地，如中国、日本等大乘教区，阿弥陀佛信仰也尤为繁盛和重要。而汉传佛教的净土宗，则完全以往生阿弥陀佛的西方净土作为专修的法门。', '36.961823,111.973526', '{images_webp/xifangshengjingdianemituofo_1.webp,images_webp/xifangshengjingdianemituofo_2.webp,images_webp/xifangshengjingdianemituofo_3.webp,images_webp/xifangshengjingdianemituofo_4.webp,images_webp/xifangshengjingdianemituofo_5.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (40, '厕所', '', '', '{}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (56, '西方圣境殿 观音菩萨', '观世音菩萨，又名观音菩萨，中国古典小说《西游记》中的角色。五方五老之一，七佛之师，身居南海普陀落伽山潮音洞，全称“南海普陀落伽山大慈大悲救苦救难灵感观世音菩萨”，头扎盘龙髻，身穿素罗袍，眉如小月，眼似双星，玉面生喜，朱唇一点红，手持净瓶甘露垂杨柳，解八难，度群生，救苦寻声，万称万应，法力无边，
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (57, '西方圣境殿 大势至菩萨', '大势至菩萨（梵音名号：Mahāsthāmaprāpta，藏音名号：Mthu—chen—thob，音译：摩诃娑太摩钵罗钵跢，又称为得大势菩萨或大精进菩萨，简称势至菩萨，菩萨以智慧光普照一 切，令众生离三涂，得无上力；又彼行时，十方世界一切地皆震动，故称大势至，佛教八大菩萨之一。在净土宗中，被奉为“法界初祖”，与观世音菩萨同为西方极乐世界阿弥陀佛之胁侍，是阿弥陀佛右胁侍，三者合称为“西方三圣”或“阿弥陀三尊”，；在藏传佛教密宗中，大势至菩萨以忿怒相“金刚手菩萨”化现，与文殊菩萨、观世音菩萨合称“三族旌尊”，分别代表智、仁、勇
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (58, '空王行祠塑像', '建于明万历41年（公元1613年）距今413年的历史。殿中供奉的是空王古佛田志超，他是汉人成佛第一尊。据殿前立于万历41年（1613年）的《创建空王行祠碑记》中记载“夫空王佛者，乃往昔久远劫中苦行修道得成。佛名曰空王如来，为一大事因缘，出现于世，自浮示迹，降入凡俗。溯其源流，乃知古佛系陕西冯翊府人，俗姓田氏，寄居在太原府榆次县原涡村，自幼斋素，聪明智慧，迥出常人。通过碑文我们了解到:空王古佛原名空王如来，是过去佛之一，因为一件大事的缘由，降入到世间，投胎转世到了太原府榆次县原涡村的田氏家族当中，俗名为田志超。相传他先后到过太原的开化寺，介休义棠虹霁寺，最后在绵山坐化成真。在绵山云峰寺至今都有他的包骨真身像，所谓包骨真身像就是他坐化成真之后在其外围包裹一层薄泥的塑像。关于田志超的故事在介休流传很多，碑文中有相应的记载:“又诣介休县华严洪济寺，自发肯心，担水赴工，至动四天王，使钟担水。因主僧清晨识破，将钟抛下，漂至河津。”故事讲述的是田志超在介休虹霁寺时，恰逢寺庙大兴土木，挑水是最累的活儿，他独自承揽，众沙弥感到疑惑:为何白天和他们一起干活晚上还有力气挑水呢？一日傍晚，在好奇心的驱使下，众沙弥偷偷观察，发现田志超盘腿坐于地上，口中念着咒语，鹿兔仙子正抬着一口钟挑水，众沙弥吓得大叫一声，吓跑了鹿兔仙子，那口钟就顺着坡滚落了下去。被钟滚过的坡现在叫滚钟坡，这个坡上的草至今还是躺着生长的，已经形成一个奇观。再说田志超，滚钟的故事传开之后，他不愿继续留在虹霁寺，选择去往绵山隐居修行。我们来继续看看碑中的记载:“至唐贞观八年，亢旱不雨，长安耆老来乞甘雨，佛命摩斯施雨，比时摩斯淘米，将米泔西望三杓，得雨三日有验。唐王闻此大悦，遂命銮驾访见真人，空王等三圣不肯屈见，以故隐匿入灭，即今抱腹岩摩斯塔银公洞是也。唐王焚香处祝乞示明应，天空中掷下金字牌，书写“入灭圣人即空王佛。”这个故事是说:在唐贞观8年，陕西大旱，长安的长老来绵山拜见空王古佛祈求甘雨，佛祖命摩斯施雨，当时摩斯正在淘米，于是将淘米水向西面长安城的方向舀了三勺，之后长安城连续下了三天大雨。李世民大悦，于是亲率大臣来绵山谢雨。走到山下，田志超因不愿会面作法让天降大雨，将李世民挡在山下。但李世民不顾大雨滂沱和道路的泥泞执意要面见这位高僧，为难之际田志超选择了坐化圆寂，这时天空中佛光普照，天空中掷下一块金字牌，上书“入灭圣人即空王佛”，意思是告诉李世民刚刚圆寂的佛祖是空王古佛。长久以来，空王古佛的灵验故事被百姓传诵，去绵山许愿的香客络绎不绝。因张壁古堡是通往绵山的必经之路，所以张壁人在此修建空王行祠，既是感激佛祖的恩典，也是方便善男信女的朝拜。每年农历3月17是空王古佛的圣诞，四面八方的百姓都会前来祈福许愿。接下来我们移步到大殿中参观，据万历41年（1613年）的《创建空王行祠碑记》中记载:“建立行祠三楹，内塑空王、摩斯、银公三圣，彩画金妆，壁绘如来功行。”您看正中供奉的便是空王古佛田志超，两边是摩斯圣者和银公圣者。三尊均为贴金造像，后面背光为镂空泥塑，相当精美，可以与平遥双林寺的泥塑相媲美。空王古佛背光高约3米，最外围一圈是跳动的火焰，象征佛祖法力无边；里边一圈的花朵为富贵牡丹，雍容华贵；再里边一圈是莲花，象征佛祖的清净；佛头两侧为龙凤呈祥；佛头上方为华盖，象征佛祖地位至高无上；下方是金刚力士托莲花宝座。', NULL, '{images_webp/kongwangxingcisuxiang_1.webp,images_webp/kongwangxingcisuxiang_2.webp,images_webp/kongwangxingcisuxiang_3.webp,images_webp/kongwangxingcisuxiang_4.webp,images_webp/kongwangxingcisuxiang_5.webp,images_webp/kongwangxingcisuxiang_6.webp,images_webp/kongwangxingcisuxiang_7.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (60, '普贤菩萨', '普贤菩萨是大乘佛教四大菩萨之一，在张壁古堡三大士殿中，位于观音菩萨右侧。普贤菩萨是释迦牟尼佛的右胁侍，与左胁侍文殊菩萨相对应，一同辅佐释迦牟尼佛于娑婆世界教化众生，辅助释迦佛弘扬佛道。普贤菩萨象征着理德、行德，代表菩萨最高行门，强调修行者不仅要有大愿心，更须修大行。常见形象为头戴宝冠，身披彩衣，手持莲花，华上置经，面如满月，乘坐六牙白象。六牙白象象征着普贤菩萨的实践精神一往无前、所向披靡。道场为四川峨眉山', '36.960530,111.972618', '{images_webp/puxianpusa_1.webp,images_webp/puxianpusa_2.webp,images_webp/puxianpusa_3.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (61, '观音菩萨', '三大士殿中的观音菩萨像位于佛坛中央，头梳高髻、戴镂空高华冠，额前头发对称涡卷、整齐分绺，两侧发辫长垂及两肩。面型长丰秀美，面相偏于中性。上身袒露，屈腿自在坐，即右腿屈起、膝盖向上，赤足踏于莲花台座上；左小腿自然下垂、赤足落于莲花足踏。右前臂抬起以腕轻搭于右膝上、柔骨纤秀的手自然下垂，手中轻握天衣飘带；左臂则于身侧竖直撑于莲座上。其坐骑为金毛犼，横伏于佛坛西侧中间的岩石座上，精壮稳健，驯服中见威严。', '36.960530,111.972618', '{images_webp/guanyinpusa_1.webp,images_webp/guanyinpusa_2.webp,images_webp/guanyinpusa_3.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (62, '三大士殿塑像，文殊菩萨，普贤菩萨，观音菩萨', '张壁古堡三大士殿是古堡内重要的佛教文化遗存，殿内供奉文殊菩萨、观音菩萨、普贤菩萨三尊核心塑像，三像并立，分别象征佛教中的 “智慧”“慈悲” 与 “大行”，共同构成 “三大士” 的经典组合。三大士殿的三尊塑像以观音菩萨为中心，文殊菩萨居左、普贤菩萨居右，呈对称排布，既符合佛教 “三大士共证菩提” 的教义，也体现了传统建筑中 “中轴对称、主次分明” 的布局逻辑。', '36.960530,111.972618', '{images_webp/sandashidiansuxiangwenshupusapuxianpusaguanyinpusa_1.webp,images_webp/sandashidiansuxiangwenshupusapuxianpusaguanyinpusa_2.webp,images_webp/sandashidiansuxiangwenshupusapuxianpusaguanyinpusa_3.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (63, '真武殿 真武大帝塑像', '张壁古堡相关殿宇中的真武大帝塑像，多遵循道教经典仪轨塑造，造型威严庄重，道教典籍中，真武大帝曾 “斩妖除魔、平定乱象”，被视为 “降妖伏魔、护持正道” 的象征，民间信仰中，其职能延伸为 “护宅、保平安”，尤其契合张壁古堡作为军事堡垒 “防御外敌、守护居民” 的核心功能，因此成为古堡重要的护佑神祇。', '36.960530,111.972618', '{images_webp/zhenwudianzhenwudadisuxiang_1.webp,images_webp/zhenwudianzhenwudadisuxiang_2.webp,images_webp/zhenwudianzhenwudadisuxiang_3.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (64, '真武殿塑像龟蛇二将', '张壁古堡真武殿内的龟蛇二将，是真武大帝信仰体系中核心的护法神，其形象与寓意深度契合道教文化内涵，同时融入了古堡的信仰特色，据道教典籍记载，真武大帝修行过程中，曾收服 “龟蛇二妖”，使其弃恶从善，成为终身护法，因此二者常以 “侍从” 身份伴随真武大帝左右，形成 “主神 - 护法” 的固定组合，殿内布局也遵循这一传统，凸显真武大帝的核心地位。', '36.960530,111.972618', '{images_webp/zhenwudiansuxiangguisheerjiang_1.webp,images_webp/zhenwudiansuxiangguisheerjiang_2.webp,images_webp/zhenwudiansuxiangguisheerjiang_3.webp,images_webp/zhenwudiansuxiangguisheerjiang_4.webp,images_webp/zhenwudiansuxiangguisheerjiang_5.webp,images_webp/zhenwudiansuxiangguisheerjiang_6.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (65, '真武殿 金童玉女', '张壁古堡真武殿内的金童玉女，是真武大帝神像旁的重要侍从造像，属于道教神仙体系中 “主神伴侍” 的经典配置，其形象与寓意既遵循道教仪轨，又融入了地方民间审美，是殿内宗教造像群中兼具灵动性与象征意义的组成部分。金童形象：为少年郎模样，面容圆润清秀，眼神明亮有神，头戴道教典型冠饰，身着浅蓝色道袍，拱手而立，身形挺拔却不失活泼，尽显少年的灵动朝气。玉女形象：为青年女子风貌，面容温婉柔和，眉目清秀，头戴 “花钗冠，身着色彩清丽的服饰，姿态为站姿，身形纤秀却不失端庄，体现女性的温婉气质。', '36.960530,111.972618', '{images_webp/zhenwudianjintongyunv_1.webp,images_webp/zhenwudianjintongyunv_2.webp,images_webp/zhenwudianjintongyunv_3.webp,images_webp/zhenwudianjintongyunv_4.webp,images_webp/zhenwudianjintongyunv_5.webp,images_webp/zhenwudianjintongyunv_6.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (66, '真武殿内塑像，真武大帝，龟蛇二将，金童玉女', '张壁古堡真武殿是古堡道教文化的核心载体，殿内塑像以真武大帝为绝对核心，真武大帝塑像居于佛坛中央最高位，龟蛇二将是真武大帝的专属护法神，分列于主像两侧，金童玉女作为主神的侍从造像，位于龟蛇二将外侧。', '36.960530,111.972618', '{images_webp/zhenwudianneisuxiangzhenwudadi_1.webp,images_webp/zhenwudianneisuxiangzhenwudadi_2.webp,images_webp/zhenwudianneisuxiangzhenwudadi_3.webp,images_webp/zhenwudianneisuxiangzhenwudadi_4.webp,images_webp/zhenwudianneisuxiangzhenwudadi_5.webp,images_webp/zhenwudianneisuxiangzhenwudadi_6.webp,images_webp/zhenwudianneisuxiangzhenwudadi_7.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (67, '天王殿', '兴隆寺山门廊下为琉璃烧制的哼哈二将，把守山门。山门里是天王殿，在1947年被战火烧毁，于2017年10月重建完成对外开放。殿内悬空供奉弥勒佛，背面供奉韦陀菩萨。左右供奉着四大天王，分别是东方持国天王，手持琵琶，琵琶调弦，代表“调”，南方增长天王，手持宝剑，宝剑锋利，取谐音风，代表“风”，西方广目天王，手持一蛇，蛇顺滑，代表“顺”，北方多闻天王，手持宝伞，伞挡雨，代表“雨”，每人所持的法器寓意风调雨顺，五谷丰登。寄托了张壁人祈求生活顺遂的美好愿望。', '36.963061,111.973038', '{images_webp/tianwangdian_1.webp,images_webp/tianwangdian_2.webp,images_webp/tianwangdian_3.webp,images_webp/tianwangdian_4.webp,images_webp/tianwangdian_5.webp,images_webp/tianwangdian_6.webp,images_webp/tianwangdian_7.webp,images_webp/tianwangdian_8.webp,images_webp/tianwangdian_9.webp,images_webp/tianwangdian_10.webp,images_webp/tianwangdian_11.webp,images_webp/tianwangdian_12.webp,images_webp/tianwangdian_13.webp,images_webp/tianwangdian_14.webp,images_webp/tianwangdian_15.webp,images_webp/tianwangdian_16.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (68, '张壁礼射院', '张壁古堡礼射院，这个院落是2018年在旧民居的基础上改造而成，从2018年至今，已经举办了四届禅弓射箭比赛，吸引了全国数千名传统射箭运动爱好者前来参赛。禅弓院还是2018年、2019年两届少林禅弓射箭比赛的决赛场地，在这里诞生了8万8千元的冠军大奖。', '36.961827,111.972839', '{images_webp/zhangbilisheyuan_1.webp,images_webp/zhangbilisheyuan_2.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (69, '圣箭堂', '这个展厅建设于2018年，为了更直观的展现中国传统射艺文化。弓箭是人类最早发明的远程武器之一。学术界研究表明，在旧石器时代与新石器时代之交，有一个中石器时代，在这一时期，世界上不少地区开始发明弓箭，用于狩猎和战争。
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (70, '西方圣境殿，悬塑伎乐天', '原先殿内的悬塑为十八重天、十八重地，后期遭到破坏，我们现在看到的悬塑是2013年聘请工艺美术学家万绪德先生重新塑造，悬塑内容为伎乐天，描写了佛国的歌舞升平。', '36.961823,111.973526', '{images_webp/xifangshengjingdianxuansujiletian_1.webp,images_webp/xifangshengjingdianxuansujiletian_2.webp,images_webp/xifangshengjingdianxuansujiletian_3.webp,images_webp/xifangshengjingdianxuansujiletian_4.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (71, '张壁影子钟', '这里是张壁影子钟，是利用光影来测量时间的一 种设施，根据太阳的位置，以人为“指针”测量当时时间。利 用光影测时是我国古代较为普遍的做法，如故宫的赤道日晷。 张壁影子钟根据日晷计算原理建造，以人晷站位刻度测量时间，当人站在相对应的日期位置上，身影所指示的刻度便是当下的 时间，感兴趣的游客可以站上去亲自感受一下。', '36.963006,111.973070', '{images_webp/zhangbiyingzizhong_1.webp,images_webp/zhangbiyingzizhong_2.webp,images_webp/zhangbiyingzizhong_3.webp,images_webp/zhangbiyingzizhong_4.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (72, '弓箭展厅', '收藏弓多为清朝中期至民国时期所用弓，所展弓都是中国传统弓，是一张裸弓，不想现代弓有一整套可供射手参考的配件：搭箭台、配重、瞄准镜等。中国传统弓分为弓身和弓弦两大部分，弓身有分为弓梢、弓臂（上弓臂、下弓臂），弓把，以及元宝状的弦垫。弦垫的作用是为了减震和防止弓弦跑弦。
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (73, '地道剖面图', '进入地道之前我们先来看一下地道的概念模型图，可
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (76, '军校场 木人桩', '木人桩:为武术器材，陪练器材。以木材制造，有桩手及桩脚之设置，容许少量活动(弹性)，当作模拟敌人练习，锻炼手部之刚强性、全身整体活动性、步法之灵活性。还有一种说法， 木人桩是戚继光发明的，戚继光在武术实践中，发现了运动知觉的开发是训练技巧提高的关键，然而，戚继光武功盖世，找不到陪练，于是发明了木人桩。', '36.962027,111.973366', '{images_webp/junjiaochangmurenzhuang_1.webp,images_webp/junjiaochangmurenzhuang_2.webp,images_webp/junjiaochangmurenzhuang_3.webp,images_webp/junjiaochangmurenzhuang_4.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (77, '军校场 抛石机', '抛石机是古代一种远程重型战具，运用杠杆原理和力学原理抛射石弹或火药弹来打击对方人员或军事设施。中国在战国时期开始使用抛石机，秦汉至隋多样化发展，唐朝逐渐标准化，宋元时期达到高峰。如果张壁古堡曾有抛石机，从其历史背景推测，可能是隋唐时期的杠杆式抛石机，用于城堡防御。', '36.962027,111.973366', '{images_webp/junjiaochangpaoshiji_1.webp,images_webp/junjiaochangpaoshiji_2.webp,images_webp/junjiaochangpaoshiji_3.webp,images_webp/junjiaochangpaoshiji_4.webp,images_webp/junjiaochangpaoshiji_5.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (78, '军校场 狼牙拍', '狼牙拍：古代守城武器，明茅元仪《武备志・器式》中记载，狼牙拍是一款古代守城兵器，其制作与使用方法如下：以榆木或棕木枋制成，形制为长五尺、宽四尺五寸、厚三寸的木拍；木拍上密布数百个长五寸、重六两的狼牙铁钉，钉尖露出木拍三寸，同时在木拍四面嵌入刃刀，四角钉有铁环；使用时，用绳子通过滑车将其绞挂在城墙上，待敌人像蚂蚁般密集攀爬攻城时，扯动绳子放下狼牙拍，以此阻挡敌军攻城。', '36.962027,111.973366', '{images_webp/junjiaochanglangyapai_1.webp,images_webp/junjiaochanglangyapai_2.webp,images_webp/junjiaochanglangyapai_3.webp,images_webp/junjiaochanglangyapai_4.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (9, '关帝庙', '眼前看到就是关帝庙。这个建筑是抱厦亭，它所采用的是中国早在春秋以前就已形成的传统古建形式----抬梁式。这种世界建筑中独一无二的结构形式，成为中国建筑的重要特征。现在我们进入的是献殿，建于乾隆五十六年（1791），距今235年的历史。献殿用于古代的祭祀，所以没有墙体，这样有利于贡品的通风。抬头看到上方有块匾额，书有四字“亘古一人”，原先这里有副木刻对联，上联为：生蒲州聚涿州保豫州镇荆州为公称神称帝；下联为：扶玄德结义德斩庞德剿孟德谁人塑像塑身，言简意赅的概括了关老爷的一生。碑文：很早以前古堡人善用碑文的方式来记事，所以要了解古堡的历史很多都是来源于碑文的。我们首先来看立于康熙五十年（1711）的重修关帝庙碑记，碑文记载：明末之时，贼寇生发，寝不安席，附近乡邻，俱受侵凌，遇有贼寇来攻吾堡，壮者奋力抵敌，贼不能入，贼曰;汝村中赤面大汉，乘赤马者，是何处之兵，我等曰:请来神兵剿灭汝寇也······老百姓认为：赤面大汉乘赤马者指的是关老爷，所以老百姓在此为其建庙，希望他永远在此处护佑堡中的子民。身后这通碑是立于道光十五年的《重修仪仗补修彩绘碑记》，距今已有191年的历史，也可以说是功德碑，这里是本村捐款内容：十二两的布政司经厅，张礼维，从乾隆五十六年到道光二十四年的碑文之上，先后九次出现过他的名字，都以一些经理、起意人的身份出现，说明他为这个村子的村舍建设投入了自己的很多心血，接下来我们会路过他们家的故居。我们现在进入大殿,据不完全统计，全国有三万多处关帝庙，但我们这里与之不同的是它是倒座形式，一般的主殿都是坐北朝南，可这里的是坐南朝北，之所以这样建，就是因为碑文上记载说这里曾是关老爷显灵的地方。这个大殿最后一次复修于康熙48年（1709），距今317年的历史。正中供奉的就是关老爷：姓关，名羽，字云长，山西运城解州人，所以规模最大的关帝庙就在关老爷的老家，山西运城解州。传说：他二十四岁避难于涿州，结识了张飞、刘备，他的一生都为刘备中兴汉室而努力，也因他的忠、义、仁、勇被历朝历代的统治者推崇为英雄的典范，对他大肆赐封，侯而王，王而帝，帝而圣，圣而天，褒封不尽，庙祀无垠。（关羽死后头在洛阳，身困湖北当阳，右指湖北襄阳，左指湖北省仙桃市沔阳，面朝太阳）。关老爷在三教中各有一席之地，佛教中是一位护法神将，被称为是伽蓝菩萨；儒教中与孔子并称文武二圣，被称为是武圣人；我们现在看到的是他在道教中的地位，关圣帝君。关老爷又是一位全方位的保护神，可以司命录，佑科举，我们更多的将他称之为是财神。两侧站立的是义子关平，大将周仓，有话说：周仓无智，扛刀一世，并不是说他没有智慧，而是说他对自己的主人忠心耿耿，一直随从其左右。这个殿中最值得一看的是它的壁画，它和殿宇同期完工，也有三百多年的历史，但是工笔细腻、彩色艳丽，所描绘的是关公征战的二十五幅场景。之所以能保留这么长时间，有多方面的原因，一这里处于黄土高原，气候比较干燥；二这个殿的倒座形式，使得紫外线不能照射进来；三是村民对于它的保护。', '36.961480,111.973510', '{images_webp/guandimiao.webp,images_webp/guandimiao_1.webp,images_webp/guandimiao_2.webp,images_webp/guandimiao_3.webp,images_webp/guandimiao_4.webp,images_webp/guandimiao_5.webp,images_webp/guandimiao_6.webp,images_webp/guandimiao_7.webp,images_webp/guandimiao_8.webp,images_webp/guandimiao_9.webp,images_webp/guandimiao_10.webp,images_webp/guandimiao_11.webp,images_webp/guandimiao_12.webp,images_webp/guandimiao_13.webp,images_webp/guandimiao_14.webp,images_webp/guandimiao_15.webp,images_webp/guandimiao_16.webp,images_webp/guandimiao_17.webp,images_webp/guandimiao_18.webp}', 'Scenic area official');
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (14, '可罕庙', '提到可罕，大家都知道是对少数民族部落首领的称呼。刚刚说到山西被誉为中国第一军事要地，是胡汉融合的地方。山西境内有6座可罕庙，这里是保存最完整的一处。因为没有具体文献记载，所以此处供奉着哪位可罕有所争议。庙宇东侧有一块立于明朝天启六年(公元1626)的石碑，名为《重修可罕庙碑记》，碑文记载“可罕庙创自何代殊不可考，而中梁书延祐元年重建”。延祐元年是公元1314年，距今已有700多年历史，因此可罕庙被认为是张壁古堡最古老的一处庙宇。第二处记载“可罕神一方之保障也”，百姓认为可罕是此地的保护神，第三处记载“可罕夷狄之君长也，生为夷狄君，殁为夷狄神”意思是说可罕是东北方向的一支部落的首领，在世时是部落的首领，去世以后成为部落的神灵。张壁先民可能受到过这位可罕王的恩惠，所以世代供奉。
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (43, '琉璃视界', '琉璃视界：介休是琉璃之乡，早在北魏时期已经开窑烧造，唐代已有“琉璃寺”，历史上的介休匠人主持烧造了明代南京、北京宫殿琉璃，沈阳“一宫三陵”琉璃构件，清代故宫也有介休匠人的参与烧造。此外，西安古建、苏杭寺庙、长沙园林，也都随处可见介休琉璃的身影。
INSERT INTO public.attractions (id, name, description, "position", jpg_path, upload_by) VALUES (45, '可罕庙戏台', '2001年国家建设部于振生、孙大张两位专家及南京工程学院汪永平院士考证可罕庙戏台为元代风格，采用了“移柱减柱法”，距今已有700多年历史，是古堡内最古老的戏台，两侧八字影壁上有“龟甲福寿”纹，大梁上记载为清乾隆35年（公元1770年）重修时增设。戏台前的地面由河卵石铺砌，看似简单，其实非常讲究，是由横13条，竖5条河卵石铺砌而成的5条曲龙，寓意“五龙朝台”。还有一处由乱砖堆砌的地方是老百姓知道的最早的地道入口，可惜在抗日战争期间被日本人炸毁填埋。因为戏台下方有地道，所以唱戏时有独特的瓮音效果。戏台原先上演介休当地的特色剧种——干调秧歌。“干调”的意思是说无乐器伴奏，只凭演员自身的嗓音演唱，随着时代的发展，现在的干调秧歌已经加上了乐器伴奏，效果比以前更好。（拓展介绍：“秧歌”自然是和插秧有关。介休在远古时期处于晋阳湖中，大禹治水时打开灵石口，空出晋阳湖，才形成了现在的晋中盆地和太原盆地。之后人们便开始在田间插秧栽苗，秧苗不经太阳照射就会枯死，所以人们不得不在田间地头等太阳，为了打发时间便把自己生活中琐碎的事情用唱的方式演绎出来，到后期逐步形成固定的词调。就如祁太秧歌、孝义的碗碗腔一样，都是地方剧种形式。京剧当中有生旦净末丑等角色，在干调秧歌中也有类似的角色分别叫黑胡子、白胡子、正旦、小旦、杂八角。）', '36.961950,111.973330', '{images_webp/kehanmiaoxitai_1.webp,images_webp/kehanmiaoxitai_2.webp,images_webp/kehanmiaoxitai_3.webp,images_webp/kehanmiaoxitai_4.webp,images_webp/kehanmiaoxitai_5.webp,images_webp/kehanmiaoxitai_6.webp,images_webp/kehanmiaoxitai_7.webp,images_webp/kehanmiaoxitai_8.webp}', 'Scenic area official');
